import{_ as t,a0 as p,w as o,s as r,I as l,a1 as a,A as e,x as n,ao as b}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"如何在 Debian 10 上安装 Ansible | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Debian 10 上安装 Ansible | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Debian 10 上安装 Ansible | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Debian 10 上安装 Ansible | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190825 How to Install Ansible (Automation Tool) on Debian 10 (Buster)","title":"如何在 Debian 10 上安装 Ansible","tag":"201908","desc":""},"relativePath":"201908/20190825 How to Install Ansible (Automation Tool) on Debian 10 (Buster).md","filePath":"[post].md"}'),d={name:"201908/20190825 How to Install Ansible (Automation Tool) on Debian 10 (Buster).md"};function h(u,s,g,c,k,m){const i=p("Link");return o(),r("div",null,[l("p",null,[a(i,{href:"collector:",title:"lujun9972"},{default:e(()=>[...s[0]||(s[0]=[n("#",-1)])]),_:1}),s[5]||(s[5]=n(": subject: (How to Install Ansible (Automation Tool) on Debian 10 (Buster)) ",-1)),a(i,{href:"collector:",title:"lujun9972"},{default:e(()=>[...s[1]||(s[1]=[n("#",-1)])]),_:1}),s[6]||(s[6]=n(": via: (",-1)),a(i,{href:"https://www.linuxtechi.com/install-ansible-automation-tool-debian10/"},{default:e(()=>[...s[2]||(s[2]=[n("https://www.linuxtechi.com/install-ansible-automation-tool-debian10/",-1)])]),_:1}),s[7]||(s[7]=n(") ",-1)),a(i,{href:"collector:",title:"lujun9972"},{default:e(()=>[...s[3]||(s[3]=[n("#",-1)])]),_:1}),s[8]||(s[8]=n(": author: (Pradeep Kumar ",-1)),a(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...s[4]||(s[4]=[n("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),s[9]||(s[9]=n(")",-1))]),s[25]||(s[25]=b(`<h1 id="如何在-debian-10-上安装-ansible" tabindex="-1">如何在 Debian 10 上安装 Ansible <a class="header-anchor" href="#如何在-debian-10-上安装-ansible" aria-label="Permalink to “如何在 Debian 10 上安装 Ansible”">​</a></h1><p>在如今的 IT 领域，自动化一个是热门话题，每个组织都开始采用自动化工具，像 Puppet、Ansible、Chef、CFEngine、Foreman 和 Katello。在这些工具中，Ansible 是几乎所有 IT 组织中管理 UNIX 和 Linux 系统的首选。在本文中，我们将演示如何在 Debian 10 Sever 上安装和使用 Ansible。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/08/Ansible-Install-Debian10.jpg" alt="Ansible-Install-Debian10"></p><p>我的实验室环境：</p><ul><li>Debian 10 – Ansible 服务器/ 控制节点 – 192.168.1.14</li><li>CentOS 7 – Ansible 主机 （Web 服务器）– 192.168.1.15</li><li>CentOS 7 – Ansible 主机（DB 服务器）– 192.169.1.17</li></ul><p>我们还将演示如何使用 Ansible 服务器管理 Linux 服务器</p><h3 id="在-debian-10-server-上安装-ansible" tabindex="-1">在 Debian 10 Server 上安装 Ansible <a class="header-anchor" href="#在-debian-10-server-上安装-ansible" aria-label="Permalink to “在 Debian 10 Server 上安装 Ansible”">​</a></h3><p>我假设你的 Debian 10 中有一个拥有 root 或 sudo 权限的用户。在我这里，我有一个名为 <code>pkumar</code> 的本地用户，它拥有 sudo 权限。</p><p>Ansible 2.7 包存在于 Debian 10 的默认仓库中，在命令行中运行以下命令安装 Ansible，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo apt install ansible -y</span></span></code></pre></div><p>运行以下命令验证 Ansible 版本，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ansible --version</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/08/ansible-version.jpg" alt="ansible-version"></p><p>要安装最新版本的 Ansible 2.8，首先我们必须设置 Ansible 仓库。</p><p>一个接一个地执行以下命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ echo &quot;deb http://ppa.launchpad.net/ansible/ansible/ubuntu bionic main&quot; | sudo tee -a /etc/apt/sources.list</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo apt-key adv --keyserver keyserver.ubuntu.com --recv-keys 93C4A3FD7BB9C367</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo apt install ansible -y</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo ansible --version</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/08/latest-ansible-version.jpg" alt="latest-ansible-version"></p><h3 id="使用-ansible-管理-linux-服务器" tabindex="-1">使用 Ansible 管理 Linux 服务器 <a class="header-anchor" href="#使用-ansible-管理-linux-服务器" aria-label="Permalink to “使用 Ansible 管理 Linux 服务器”">​</a></h3><p>请参考以下步骤，使用 Ansible 控制器节点管理 Linux 类的服务器，</p><h4 id="步骤-1-在-ansible-服务器及其主机之间交换-ssh-密钥" tabindex="-1">步骤 1：在 Ansible 服务器及其主机之间交换 SSH 密钥 <a class="header-anchor" href="#步骤-1-在-ansible-服务器及其主机之间交换-ssh-密钥" aria-label="Permalink to “步骤 1：在 Ansible 服务器及其主机之间交换 SSH 密钥”">​</a></h4><p>在 Ansible 服务器生成 ssh 密钥并在 Ansible 主机之间共享密钥。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo -i</span></span>
<span class="line"><span>root@linuxtechi:~# ssh-keygen</span></span>
<span class="line"><span>root@linuxtechi:~# ssh-copy-id root@linuxtechi</span></span>
<span class="line"><span>root@linuxtechi:~# ssh-copy-id root@linuxtechi</span></span></code></pre></div><h4 id="步骤-2-创建-ansible-主机清单" tabindex="-1">步骤 2：创建 Ansible 主机清单 <a class="header-anchor" href="#步骤-2-创建-ansible-主机清单" aria-label="Permalink to “步骤 2：创建 Ansible 主机清单”">​</a></h4><p>安装 Ansible 后会自动创建 <code>/etc/ansible/hosts</code>，在此文件中我们可以编辑 Ansible 主机或其客户端。我们还可以在家目录中创建自己的 Ansible 主机清单，</p><p>运行以下命令在我们的家目录中创建 Ansible 主机清单。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ vi $HOME/hosts</span></span>
<span class="line"><span>[Web]</span></span>
<span class="line"><span>192.168.1.15</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[DB]</span></span>
<span class="line"><span>192.168.1.17</span></span></code></pre></div><p>保存并退出文件。</p><p>注意：在上面的主机文件中，我们也可以使用主机名或 FQDN，但为此我们必须确保 Ansible 主机可以通过主机名或者 FQDN 访问。</p><h4 id="步骤-3-测试和使用默认的-ansible-模块" tabindex="-1">步骤 3：测试和使用默认的 Ansible 模块 <a class="header-anchor" href="#步骤-3-测试和使用默认的-ansible-模块" aria-label="Permalink to “步骤 3：测试和使用默认的 Ansible 模块”">​</a></h4><p>Ansible 附带了许多可在 <code>ansible</code> 命令中使用的默认模块，示例如下所示。</p><p>语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ansible -i &lt;host_file&gt; -m &lt;module&gt; &lt;host&gt;</span></span></code></pre></div><p>这里：</p><ul><li><code>-i ~/hosts</code>：包含 Ansible 主机列表</li><li><code>-m</code>：在之后指定 Ansible 模块，如 ping 和 shell</li><li><code>&lt;host&gt;</code>：我们要运行 Ansible 模块的 Ansible 主机</li></ul><p>使用 Ansible ping 模块验证 ping 连接，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ansible -i ~/hosts -m ping all</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo ansible -i ~/hosts -m ping Web</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo ansible -i ~/hosts -m ping DB</span></span></code></pre></div><p>命令输出如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/08/Ansible-ping-module-examples.jpg" alt="Ansible-ping-module-examples"></p><p>使用 shell 模块在 Ansible 主机上运行 shell 命令</p><p>语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ansible -i &lt;hosts_file&gt; -m shell -a &lt;shell_commands&gt;  &lt;host&gt;</span></span></code></pre></div><p>例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ansible -i ~/hosts -m shell -a &quot;uptime&quot; all</span></span>
<span class="line"><span>192.168.1.17 | CHANGED | rc=0 &gt;&gt;</span></span>
<span class="line"><span> 01:48:34 up  1:07,  3 users,  load average: 0.00, 0.01, 0.05</span></span>
<span class="line"><span></span></span>
<span class="line"><span>192.168.1.15 | CHANGED | rc=0 &gt;&gt;</span></span>
<span class="line"><span> 01:48:39 up  1:07,  3 users,  load average: 0.00, 0.01, 0.04</span></span>
<span class="line"><span></span></span>
<span class="line"><span>root@linuxtechi:~$</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo ansible -i ~/hosts -m shell -a &quot;uptime ; df -Th / ; uname -r&quot; Web</span></span>
<span class="line"><span>192.168.1.15 | CHANGED | rc=0 &gt;&gt;</span></span>
<span class="line"><span> 01:52:03 up  1:11,  3 users,  load average: 0.12, 0.07, 0.06</span></span>
<span class="line"><span>Filesystem              Type  Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/mapper/centos-root xfs    13G 1017M   12G   8% /</span></span>
<span class="line"><span>3.10.0-327.el7.x86_64</span></span>
<span class="line"><span></span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>上面的命令输出表明我们已成功设置 Ansible 控制器节点。</p><p>让我们创建一个安装 nginx 的示例剧本，下面的剧本将在所有服务器上安装 nginx，这些服务器是 Web 主机组的一部分，但在这里，我的主机组下只有一台 centos 7 机器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ vi nginx.yaml</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>- hosts: Web</span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - name: Install latest version of nginx on CentOS 7 Server</span></span>
<span class="line"><span>      yum: name=nginx state=latest</span></span>
<span class="line"><span>    - name: start nginx</span></span>
<span class="line"><span>      service:</span></span>
<span class="line"><span>          name: nginx</span></span>
<span class="line"><span>          state: started</span></span></code></pre></div><p>现在使用以下命令执行剧本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ansible-playbook -i ~/hosts  nginx.yaml</span></span></code></pre></div><p>上面命令的输出类似下面这样，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/08/nginx-installation-playbook-debian10.jpg" alt="nginx-installation-playbook-debian10"></p><p>这表明 Ansible 剧本成功执行了。</p><p>本文就是这些了，请分享你的反馈和评论。</p><hr>`,53)),l("p",null,[s[11]||(s[11]=n("via: ",-1)),a(i,{href:"https://www.linuxtechi.com/install-ansible-automation-tool-debian10/"},{default:e(()=>[...s[10]||(s[10]=[n("https://www.linuxtechi.com/install-ansible-automation-tool-debian10/",-1)])]),_:1})]),l("p",null,[s[16]||(s[16]=n("作者：",-1)),a(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...s[12]||(s[12]=[n("Pradeep Kumar",-1)])]),_:1}),s[17]||(s[17]=n(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[13]||(s[13]=[n("lujun9972",-1)])]),_:1}),s[18]||(s[18]=n(" 译者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:e(()=>[...s[14]||(s[14]=[n("geekpi",-1)])]),_:1}),s[19]||(s[19]=n(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[15]||(s[15]=[n("wxy",-1)])]),_:1})]),l("p",null,[s[22]||(s[22]=n("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[20]||(s[20]=[n("LCTT",-1)])]),_:1}),s[23]||(s[23]=n(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:e(()=>[...s[21]||(s[21]=[n("Linux中国",-1)])]),_:1}),s[24]||(s[24]=n(" 荣誉推出",-1))])])}const v=t(d,[["render",h]]);export{A as __pageData,v as default};
